{"file_path":"C:\Users\18749\Documents\honor-king\scripts\core\SfxManager.gd","new_string":"# 独立 SFX 池：找空闲播放器，全忙则轮询顶替（不影响播报单通道）
func _play_sfx(key: String) -> void:
	# 同类短音节流（受击/金币/施法叠得太密会糊）
	var gap: int = int(_SFX_MIN_GAP.get(key, 0))
	if gap > 0:
		var now := Time.get_ticks_msec()
		if now - int(_sfx_last.get(key, -100000)) < gap:
			return
		_sfx_last[key] = now
	var stream: AudioStream = _sfx_stream(key)
	if stream == null:
		return
	var sp := _free_sfx_player()
	sp.stream = stream
	# 合成短音峰值比 mp3 低，抬一点；再做轻微变调避免机械重复
	sp.volume_db = 2.0 if _SYNTH.has(key) else 0.0
	sp.pitch_scale = randf_range(0.97, 1.03) if _SYNTH.has(key) else 1.0
	sp.play()

# 取（并缓存）短音流：合成键优先，其次 audio/ 文件
func _sfx_stream(key: String) -> AudioStream:
	var cached: AudioStream = _sfx_loaded.get(key)
	if cached != null:
		return cached
	var stream: AudioStream = null
	if _SYNTH.has(key):
		stream = _build_synth(key)
	elif _SFX_PATHS.has(key):
		var path: String = _SFX_PATHS[key]
		if ResourceLoader.exists(path):
			stream = load(path)
	if stream != null:
		_sfx_loaded[key] = stream
	return stream

func _free_sfx_player() -> AudioStreamPlayer:
	for s in _sfx:
		if not s.playing:
			return s
	var sp: AudioStreamPlayer = _sfx[_sfx_next % _sfx.size()]
	_sfx_next += 1
	return sp

# 程序化合成 16bit/22.05kHz 单声道短音（首次播放时生成并缓存）
func _build_synth(key: String) -> AudioStreamWAV:
	var cfg: Dictionary = _SYNTH.get(key, {})
	if cfg.is_empty():
		return null
	var notes: Array = cfg.get("notes", [])
	var kind := str(cfg.get("kind", "sweep"))
	if kind == "arp" and notes.is_empty():
		return null
	const RATE := 22050
	var dur: float = float(cfg.get("dur", 0.2))
	var n := int(dur * RATE)
	if n <= 0:
		return null
	var vol: float = float(cfg.get("vol", 0.25))
	var decay: float = float(cfg.get("decay", 3.0))
	var noise_amt: float = float(cfg.get("noise", 0.0))
	var f0: float = float(cfg.get("f0", 440.0))
	var f1: float = float(cfg.get("f1", f0))
	var step: float = float(cfg.get("step", 0.08))
	var harmonic: float = float(cfg.get("harmonic", 2.0))
	var rng := RandomNumberGenerator.new()
	rng.seed = hash(key)
	var data := PackedByteArray()
	data.resize(n * 2)
	var phase := 0.0
	var lp := 0.0
	for i in n:
		var t := float(i) / float(RATE)
		var s := 0.0
		var env := 1.0
		if kind == "arp":
			# 琶音：每 step 换一个音，音内指数衰减
			var idx := mini(int(t / step), notes.size() - 1)
			var local := fmod(t, step) / step
			env = exp(-3.4 * local) * (1.0 - 0.5 * t / dur)
			phase += TAU * float(notes[idx]) / float(RATE)
			s = sin(phase) * 0.8 + sin(phase * 2.0) * 0.12
		else:
			var u := t / dur
			env = exp(-decay * u) * minf(1.0, t / 0.005)   # 5ms 起音，避免爆音
			if kind == "thump":
				var tf := f0 * pow(maxf(f1, 1.0) / f0, u)   # 低频下坠
				phase += TAU * tf / float(RATE)
				s = sin(phase)
			elif kind == "bell":
				phase += TAU * f0 / float(RATE)
				s = sin(phase) + sin(phase * harmonic) * 0.35 + sin(phase * 3.01) * 0.12
			else:
				var sf := lerp(f0, f1, u * u)   # 频率上扫
				phase += TAU * sf / float(RATE)
				s = sin(phase) * 0.85 + sin(phase * 2.0) * 0.10
			if noise_amt > 0.0:
				lp = lp * 0.72 + rng.randf_range(-1.0, 1.0) * 0.28   # 一阶低通白噪声
				s += lp * noise_amt
		data.encode_s16(i * 2, int(clampf(s * env * vol, -1.0, 1.0) * 32767.0))
	var st := AudioStreamWAV.new()
	st.format = AudioStreamWAV.FORMAT_16_BITS
	st.mix_rate = RATE
	st.stereo = false
	st.data = data
	return st","old_string":"# 独立 SFX 池：找空闲播放器，全忙则轮询顶替（不影响播报单通道）
func _play_sfx(key: String) -> void:
	if not _SFX_PATHS.has(key):
		return
	var path: String = _SFX_PATHS[key]
	if not ResourceLoader.exists(path):
		return
	var stream: AudioStream = _sfx_loaded.get(key)
	if stream == null:
		stream = load(path)
		_sfx_loaded[key] = stream
	var sp: AudioStreamPlayer = null
	for s in _sfx:
		if not s.playing:
			sp = s
			break
	if sp == null:
		sp = _sfx[_sfx_next % _sfx.size()]
		_sfx_next += 1
	sp.stream = stream
	sp.play()"}

