import re, sys
files = r"scripts\core\SfxManager.gd", r"scripts\entities\Hero.gd", r"scripts\entities\GameEntity.gd", r"scripts\ui\UI_Manager.gd", r"scripts\net\NetClientBattle.gd"
for f in files:
    src = open(f, encoding="utf-8").read()
    # strip comments and strings crudely for bracket balance
    out=[]; i=0; n=len(src); state=0
    while i<n:
        c=src[i]
        if state==0:
            if c=='#':
                j=src.find('\n', i); i = n if j<0 else j; continue
            if c in ('"', "'"):
                q=c; i+=1; state=1; continue
            out.append(c); i+=1
        elif state==1:
            if c=='\\': i+=2; continue
            if c==q: state=0
            i+=1
    code=''.join(out)
    pairs={'(':')','[':']','{':'}'}
    stack=[]; line=1; errs=[]
    for c in code:
        if c=='\n': line+=1
        elif c in pairs: stack.append((c,line))
        elif c in pairs.values():
            if not stack or pairs[stack[-1][0]]!=c:
                errs.append(f"unexpected {c} at line {line}"); break
            stack.pop()
    print(f, "OK" if not errs and not stack else (errs, stack[-3:]))
    # indentation sanity: any line starting with spaces after a tab context
    bad=[i+1 for i,l in enumerate(src.split('\n')) if re.match(r'^\t* +', l) and l.strip()]
    print("  space-indent lines:", len(bad), bad[:5])
