```gdscript
func _cfg_skill(hero: String, slot: int, stype: int) -> Dictionary:
	var el := _el_of(hero)
	var fac := _detune("sk:" + hero + ":" + str(slot), 5)
	var notes: Array = (_EL_NOTES.get(el, _EL_NOTES["arcane"]) as Array).duplicate()
	var base: Dictionary = (_EL_SFX.get(el, _EL_SFX["arcane"]) as Dictionary).duplicate(true)
	var cfg := base
	var vol := 0.26
	var dur := 0.26
	match stype:
		1:  # 范围
			dur = 0.34; vol = 0.30
			cfg["kind"] = "sweep"
			cfg["f0"] = float(cfg.get("f0", 420.0)) * 0.62
			cfg["f1"] = float(cfg.get("f1", 820.0)) * 0.85
			cfg["noise"] = 0.16
		2:  # 增益
			cfg = {"kind": "arp", "notes": notes, "step": 0.07, "dur": 0.36, "vol": 0.26}
		3:  # 线性
			dur = 0.22; vol = 0.26
			if str(cfg.get("kind","")) != "sweep": cfg = {"kind": "sweep", "f0": 760.0, "f1": 1700.0, "noise": 0.14}
		4:  # 位移
			cfg = {"kind": "sweep", "f0": 420.0, "f1": 1400.0, "dur": 0.16, "vol": 0.26, "noise": 0.28, "decay": 4.5}
		6:  # 护盾
			cfg = {"kind": "pad", "notes": notes, "dur": 0.55, "vol": 0.24}
		_:
			pass
	if stype != 6 and stype != 2:
		cfg["dur"] = dur
		cfg["vol"] = vol
		cfg["decay"] = float(cfg.get("decay", 3.0))
	# 大招更重
	if slot == 2 and stype not in [2, 6]:
		cfg["dur"] = float(cfg.get("dur", dur)) * 1.5
		cfg["vol"] = float(cfg.get("vol", vol)) * 1.12
		cfg["f0"] = float(cfg.get("f0", 440.0)) * 0.82
		if cfg.has("f1"): cfg["f1"] = float(cfg["f1"]) * 0.9
	# 英雄/槽位微调
	for k in ["f0", "f1"]:
		if cfg.has(k): cfg[k] = float(cfg[k]) * fac
	if cfg.has("notes"):
		var ns: Array = cfg["notes"].duplicate()
		for i in ns.size(): ns[i] = float(ns[i]) * fac
		cfg["notes"] = ns
	return cfg
```
