{"command":"@'
extends Node

func _ready() -> void:
	var sm := get_node_or_null("/root/SfxManager")
	DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path("res://_sfx_out"))
	var mins := ["melee","ranged","siege","super","dragon","storm","shadow_dragon"]
	var beasts := ["pig","bird","worm","wolf","lizard","monkey","red_buff","blue_buff","tyrant","shadow_tyrant","dragon","shadow_dragon","storm_dragon","spatial_spirit","river_spirit"]
	var towers := ["outer","inner","high","crystal"]
	var ok := 0
	var bad := 0
	for t in mins:
		var st: AudioStream = sm._sfx_stream("mn:" + t)
		if st == null: bad += 1; print("MN_FAIL ", t)
		else: ok += 1
	for b in beasts:
		var st: AudioStream = sm._sfx_stream("jn:" + b)
		if st == null: bad += 1; print("JN_FAIL ", b)
		else: ok += 1
	for t in towers:
		for team in [0, 1]:
			var st: AudioStream = sm._sfx_stream("tw:%s:%d" % [t, team])
			if st == null: bad += 1; print("TW_FAIL ", t, team)
			else: ok += 1
	print("PROBE ok=", ok, " bad=", bad)
	sm._sfx_stream("mn:melee").save_to_wav("res://_sfx_out/mn_melee.wav")
	sm._sfx_stream("mn:siege").save_to_wav("res://_sfx_out/mn_siege.wav")
	sm._sfx_stream("mn:shadow_dragon").save_to_wav("res://_sfx_out/mn_shadow.wav")
	sm._sfx_stream("jn:wolf").save_to_wav("res://_sfx_out/jn_wolf.wav")
	sm._sfx_stream("jn:tyrant").save_to_wav("res://_sfx_out/jn_tyrant.wav")
	sm._sfx_stream("tw:outer:0").save_to_wav("res://_sfx_out/tw_outer_own.wav")
	sm._sfx_stream("tw:crystal:1").save_to_wav("res://_sfx_out/tw_crystal_enemy.wav")
	# 触发路径（无英雄/无输入时应安全静默）
	sm.try_minion_attack_sfx("melee", Vector3.ZERO)
	sm.try_jungle_attack_sfx("wolf", Vector3.ZERO)
	sm.try_tower_attack_sfx(0, "outer", Vector3.ZERO)
	await get_tree().create_timer(0.2).timeout
	get_tree().quit()
