155: static func _build_ground_shader() -> Shader:
157: sh.code = _GROUND_CODE
160: const _GROUND_CODE := """
167: uniform vec4 tint : source_color = vec4(1.0);
168: uniform vec4 emission_color : source_color = vec4(0.0, 0.0, 0.0, 1.0);
173: uniform float ground_roughness = 0.95;
182: float lane_d = min(min(abs(abs(wp.x) - 55.0), abs(abs(wp.z) - 55.0)), abs(wp.x + wp.z) * 0.7071068);
183: float lane_m = 1.0 - smoothstep(7.0, 13.0, lane_d);
187: float jungle_m = clamp(1.0 - lane_m - river_m - hg_m, 0.0, 1.0) * edge_m;
204: ROUGHNESS = ground_roughness;
206: EMISSION = emission_color.rgb * emission_strength;
216: uniform vec3 shallow_color : source_color = vec3(0.24, 0.56, 0.57);
217: uniform vec3 deep_color : source_color = vec3(0.035, 0.125, 0.185);
218: uniform vec3 foam_color : source_color = vec3(0.88, 0.95, 0.93);
219: uniform vec3 sky_color : source_color = vec3(0.42, 0.60, 0.80);
274: vec3 col = mix(shallow_color, deep_color, center * 0.95);
282: col = mix(col, foam_color, clamp(foam * 0.55, 0.0, 1.0));
283: col = mix(col, foam_color, wet_line * 0.30);
288: col = mix(col, sky_color, clamp(fres * 0.42, 0.0, 0.42));
311: sand_mat.albedo_color = Color(0.30, 0.27, 0.215)
315: var pm := PlaneMesh.new()
330: rock_mat.albedo_color = Color(0.19, 0.21, 0.215)
359: reed_mat.albedo_color = Color(0.27, 0.34, 0.17)
388: lily_mat.albedo_color = Color(0.20, 0.36, 0.21)
415: var grass := FastNoiseLite.new()
416: grass.seed = 7
417: grass.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
418: grass.frequency = 0.045
427: var n: float = grass.get_noise_2d(x, z) * 0.5 + 0.5          # 0..1 细噪声
431: var col := Color(0.17, 0.31, 0.14).lerp(Color(0.33, 0.48, 0.21), n)
432: col = col.lerp(Color(0.11, 0.20, 0.11), pt * 0.45)
436: col = col.lerp(Color(0.22, 0.28, 0.29).lerp(Color(0.30, 0.36, 0.34), n), _inside(river_d, 13.0, 3.0))

