{"command":"@'
extends SceneTree

func _initialize() -> void:
	for path in ["res://model/melee/soldier.glb", "res://model/range/archer.glb", "res://model/seige/cannon-mobile.glb", "res://model/super/character-orc.glb"]:
		var ps: PackedScene = load(path)
		var n: Node3D = ps.instantiate()
		root.add_child(n)
		var ab := _aabb(n)
		print(path, " aabb=", ab, " size=", ab.size)
		var aps: Array = []
		_collect_anims(n, aps)
		print("  anims=", aps)
		var mats: Array = []
		_collect_mats(n, mats)
		print("  mats=", mats)
		n.queue_free()
	quit()

func _aabb(n: Node) -> AABB:
	var out := AABB()
	var first := true
	for c in n.find_children("*", "MeshInstance3D", true, false):
		var m: MeshInstance3D = c
		var b: AABB = m.global_transform * m.get_aabb()
		if first: out = b; first = false
		else: out = out.merge(b)
	return out

func _collect_anims(n: Node, out: Array) -> void:
	for c in n.find_children("*", "AnimationPlayer", true, false):
		for a in c.get_animation_list():
			out.append(a)
	_collect_anims_children(n, out)
func _collect_anims_children(n: Node, out: Array) -> void:
	pass

func _collect_mats(n: Node, out: Array) -> void:
	for c in n.find_children("*", "MeshInstance3D", true, false):
		var mesh: Mesh = c.mesh
		if mesh == null: continue
		for i in mesh.get_surface_count():
			var m = c.get_active_material(i)
			if m is BaseMaterial3D:
				out.append("%s:%s" % [m.resource_name, m.albedo_color])
			elif m != null:
				out.append(str(m))
