{"content":"extends Node3D
## 临时预览：现役小兵 vs 候选古风甲士（不接入游戏）

const MinionModelScript = preload("res://scripts/entities/MinionModel.gd")

const CURRENT := {
	"melee": "res://model/melee/soldier.glb",
	"ranged": "res://model/range/archer.glb",
	"siege": "res://model/seige/cannon-mobile.glb",
	"super": "res://model/super/character-orc.glb",
}
const KINDS := ["melee", "ranged", "siege", "super"]
const XS := [-3.95, -1.35, 1.35, 3.95]
const ZS := [1.45, -1.45]

var current_root: Node3D
var proposed_root: Node3D


func _ready() -> void:
	position = Vector3(55, 0, 0)
	MapVisuals.setup_environment(self)
	_make_ground()
	_make_camera()
	current_root = _build_current()
	proposed_root = _build_proposed()
	current_root.visible = true
	proposed_root.visible = false
	_run.call_deferred()


func _run() -> void:
	await get_tree().process_frame
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://screenshots/minion_current.png")
	current_root.visible = false
	proposed_root.visible = true
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://screenshots/minion_proposed.png")
	print("MINION_PREVIEW_DONE")
	get_tree().quit()


func _save(path: String) -> void:
	var img := get_viewport().get_texture().get_image()
	if img != null:
		img.save_png(path)
		print("saved ", path, " ", img.get_size())


func _make_ground() -> void:
	var mi := MeshInstance3D.new()
	var pm := PlaneMesh.new()
	pm.size = Vector2(40, 40)
	mi.mesh = pm
	mi.material_override = MapVisuals.ground_material()
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)


func _make_camera() -> void:
	var cam := Camera3D.new()
	cam.fov = 40.0
	cam.near = 0.05
	cam.far = 80.0
	add_child(cam)
	cam.position = Vector3(0, 8.2, 10.5)
	cam.look_at(Vector3(0, 0.75, 0))
	cam.make_current()


func _build_current() -> Node3D:
	var root := Node3D.new()
	root.name = "Current"
	add_child(root)
	for i in range(KINDS.size()):
		var kind: String = KINDS[i]
		for team in [0, 1]:
			var ps: PackedScene = load(CURRENT[kind])
			if ps == null:
				continue
			var inst: Node3D = ps.instantiate()
			var sc := NetModels.minion_scale(kind)
			inst.scale = Vector3.ONE * sc
			var holder := Node3D.new()
			holder.position = Vector3(XS[i], 0, ZS[team])
			holder.add_child(inst)
			root.add_child(holder)
			UnitVisuals.tint_team(inst, team)
			_start_idle(inst)
	return root


func _build_proposed() -> Node3D:
	var root := Node3D.new()
	root.name = "Proposed"
	add_child(root)
	for i in range(KINDS.size()):
		var kind: String = KINDS[i]
		for team in [0, 1]:
			var inst: Node3D = MinionModelScript.build(kind, team)
			var holder := Node3D.new()
			holder.position = Vector3(XS[i], 0, ZS[team])
			holder.add_child(inst)
			root.add_child(holder)
			var strength := float(inst.get_meta("tint_strength", 0.5))
			UnitVisuals.tint_team(inst, team, strength)
	return root


func _start_idle(n: Node3D) -> void:
	for c in n.find_children("*", "AnimationPlayer", true, false):
		var ap: AnimationPlayer = c
		if ap.has_animation("idle"):
			ap.play("idle")
			ap.advance(0.35)
			return
