func _build_close(proposed: bool) -> Node3D:
	var root := Node3D.new()
	root.name = "CloseProposed" if proposed else "CloseCurrent"
	add_child(root)
	var xs := [-3.05, -1.02, 1.02, 3.05]
	for i in range(KINDS.size()):
		var kind: String = KINDS[i]
		var inst: Node3D
		if proposed:
			inst = MinionModelScript.build(kind, 0)
		else:
			var ps: PackedScene = load(CURRENT[kind])
			if ps == null:
				continue
			inst = ps.instantiate()
			inst.scale = Vector3.ONE * NetModels.minion_scale(kind)
			_start_idle(inst)
		var holder := Node3D.new()
		holder.position = Vector3(xs[i], 0, 0)
		holder.add_child(inst)
		root.add_child(holder)
		var strength := float(inst.get_meta("tint_strength", 0.5))
		UnitVisuals.tint_team(inst, 0, strength)
	return root


func _start_idle(n: Node3D) -> void:
	for c in n.find_children("*", "AnimationPlayer", true, false):
		var ap: AnimationPlayer = c

