			horn_col = Color(0.72, 0.82, 0.90)
			eye_col = Color(0.45, 0.95, 1.0)
			memb_emit = Color(0.15, 0.62, 0.95)
		elif kind == "shadow_dragon":
			scale_col = Color(0.09, 0.07, 0.12)
