## 临时预览：现役主宰先锋 DragonBaby vs 候选龙形先锋（不接入游戏）

const MinionModelScript = preload("res://scripts/entities/MinionModel.gd")
const CURRENT := "res://model/dragon/DragonBaby.glb"
const KINDS := ["dragon", "storm", "shadow_dragon"]

var current_root: Node3D
var proposed_root: Node3D
var lineup_root: Node3D
var cam: Camera3D


func _ready() -> void:
	position = Vector3(55, 0, 0)
	MapVisuals.setup_environment(self)
	_make_ground()
	_make_camera()
	current_root = _build_current()
	proposed_root = _build_proposed()
	lineup_root = _build_lineup()
	current_root.visible = false
	proposed_root.visible = false
	lineup_root.visible = false
	_run.call_deferred()


func _run() -> void:
	for i in range(4):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://screenshots/dragon_bg.png")
	current_root.visible = true
	for i in range(4):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://screenshots/dragon_current.png")
	current_root.visible = false
	proposed_root.visible = true
	for i in range(4):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://screenshots/dragon_proposed.png")
	proposed_root.visible = false
	lineup_root.visible = true
	for i in range(4):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	_save("res://screenshots/dragon_lineup.png")
	print("DRAGON_PREVIEW_DONE")
	get_tree().quit()


func _save(path: String) -> void:
	var img := get_viewport().get_texture().get_image()
	if img != null:
		img.save_png(path)
		print("saved ", path, " ", img.get_size())


func _make_ground() -> void:
	var mi := MeshInstance3D.new()
	var pm := PlaneMesh.new()
	pm.size = Vector2(44, 44)
	mi.mesh = pm
	mi.material_override = MapVisuals.ground_material()
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)


func _make_camera() -> void:
	cam = Camera3D.new()
	cam.fov = 40.0
	cam.near = 0.05
	cam.far = 90.0
	add_child(cam)
	cam.position = Vector3(0, 5.6, 10.5)
	cam.look_at(to_global(Vector3(0, 0.95, 0)))
	cam.make_current()


func _build_current() -> Node3D:
	var root := Node3D.new()
	root.name = "Current"
	add_child(root)
	var xs := [-3.6, 0.0, 3.6]
	var ps: PackedScene = load(CURRENT)
	if ps == null:
		return root
	for i in range(KINDS.size()):
		var inst: Node3D = ps.instantiate()
		inst.scale = Vector3.ONE * NetModels.minion_scale("dragon")
		var holder := Node3D.new()
		holder.position = Vector3(xs[i], 0, 0)
		holder.add_child(inst)
		root.add_child(holder)
		UnitVisuals.tint_team(inst, 0)
		_start_idle(inst)
	return root


func _build_proposed() -> Node3D:
	var root := Node3D.new()
	root.name = "Proposed"
	add_child(root)
	var xs := [-3.6, 0.0, 3.6]
	for i in range(KINDS.size()):
		var kind: String = KINDS[i]
		var inst: Node3D = MinionModelScript.build(kind, 0)
		var holder := Node3D.new()
		holder.position = Vector3(xs[i], 0, 0)
		holder.add_child(inst)
		root.add_child(holder)
		var strength := float(inst.get_meta("tint_strength", 0.3))
		UnitVisuals.tint_team(inst, 0, strength)
	return root


func _build_lineup() -> Node3D:
	var root := Node3D.new()
	root.name = "Lineup"
	add_child(root)
	var xs := [-3.6, 0.0, 3.6]
	for i in range(KINDS.size()):
		for team in [0, 1]:
			var inst: Node3D = MinionModelScript.build(KINDS[i], team)
			var holder := Node3D.new()
			holder.position = Vector3(xs[i], 0, 1.5 if team == 0 else -1.5)
			holder.add_child(inst)
			root.add_child(holder)
			var strength := float(inst.get_meta("tint_strength", 0.3))
			UnitVisuals.tint_team(inst, team, strength)
	return root


func _start_idle(n: Node3D) -> void:
	for c in n.find_children("*", "AnimationPlayer", true, false):
		var ap: AnimationPlayer = c
		for anim in ap.get_animation_list():
			var an := String(anim)
			if an.to_lower().contains("idle"):
				ap.play(an)
				ap.advance(0.35)
				return
"}

