{"command":"@'
extends SceneTree
func _initialize() -> void:
	for kind in ["melee","ranged","siege","super"]:
		var m := Minion.new()
		m.display_name = kind
		m.team = 0
		m.body_radius = 0.7
		root.add_child(m)
		print(kind, " visual=", m.visual != null, " proc=", m._proc_visual, " children=", m.get_child_count())
		if m.visual:
			var aabb := (m.visual.get_node("ModelPivot").get_child(0) as MeshInstance3D).mesh.get_aabb()
			print("  aabb=", aabb, " scale=", m.visual.scale, " meta=", m.visual.get_meta("minion_model_kind"))
		m.queue_free()
	for kind in ["melee","dragon"]:
		var mm := NetModels.minion(kind, 1)
		print("client ", kind, " -> ", mm != null, " meta=", mm.get_meta("minion_model_kind") if mm and mm.has_meta("minion_model_kind") else "-")
		if mm: mm.free()
	quit()
