# 临时探针：安琪拉R光束 / 孙尚香W手雷 / 鲁班Q手雷（-- --case=angela|ssx|luban）

var bm: Node
var hero
var dummy
var f := 0
var case := "angela"
var out: Array = []
var wait_until := 0
var stage := 0
var hp0 := 0.0
var fx0 := 0


func _ready() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--case="):
			case = a.substr(7)
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")


func _log(s: String) -> void:
	out.append(s)


func _find_node(nm: String) -> Node:
	for n in get_tree().get_nodes_in_group(Vfx.GROUP_FX):
		if n.name == nm:
			return n
	return null


func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		var hn := "安琪拉" if case == "angela" else ("孙尚香" if case == "ssx" else "鲁班七号")
		bm._start_game_body(hn)
		return
	if f < 40 or bm == null:
		return
	if hero == null:
		hero = bm.hero
		if hero == null:
			f = 39
			return
		for e in get_tree().get_nodes_in_group("heroes"):
			if e != hero and e.team != hero.team:
				dummy = e
				break
		if dummy == null:
			f = 39
			return
