{"command":"@'
extends Node
func _ready() -> void:
	var bm = preload("res://scripts/core/BattleManager.gd").new()
	add_child(bm)
	for i in range(8):
		await get_tree().process_frame
	print("SEL_PROBE_VP=", get_viewport().get_visible_rect().size)
	var cu = bm.select_ui
	if cu == null:
		print("SEL_PROBE no select_ui")
		get_tree().quit(); return
	print("SEL_PROBE select_ui children=", cu.get_child_count())
	var root = cu.get_node_or_null("SelectRoot")
	if root: _dump(root, 0)
	get_tree().quit()

func _dump(n: Node, depth: int) -> void:
	if n is Control and n.is_visible_in_tree():
		var r = n.get_global_rect()
		var vp = get_viewport().get_visible_rect()
		if r.position.x < -1 or r.position.y < -1 or r.end.x > vp.end.x + 1 or r.end.y > vp.end.y + 1:
			print("SEL_OFF ", "  ".repeat(depth), n.get_path(), " rect=", r)
	for c in n.get_children():
		_dump(c, depth + 1)
