{"command":"@'
extends Node
var off := 0
func _ready() -> void:
	var bm = preload("res://scripts/core/BattleManager.gd").new()
	add_child(bm)
	for i in range(8): await get_tree().process_frame
	print("SEL_VP=", get_viewport().get_visible_rect().size)
	var cu = bm.select_ui
	var root = cu.get_node_or_null("SelectRoot") if cu else null
	if root:
		for nm in ["SelectTop","SelectMiddle","SelectBottom","SelectOurSeats","SelectFoeSeats","SelectHeroStripScroll"]:
			var n = _find(root, nm)
			if n: print("SEL_", nm, " rect=", n.get_global_rect(), " min=", n.get_combined_minimum_size())
		var seat = _find(root, "SeatOur_1")
		if seat:
			print("SEL_SeatOur_1 rect=", seat.get_global_rect(), " min=", seat.get_combined_minimum_size())
			print("SEL_SeatOur_1 children=", seat.get_child_count(), " first_h=", seat.get_child(0).get_child_count())
		var card = _find(root, "HeroCard_吕布")
		if card: print("SEL_Card rect=", card.get_global_rect(), " inner=", card.get_child(0).get_global_rect())
		var avatars := 0
		var glyphs := 0
		_scan(root, avatars, glyphs)
	print("SEL_OFF_COUNT=", off)
	get_tree().quit()

func _find(n: Node, nm: String) -> Node:
	if n.name == nm: return n
	for c in n.get_children():
		var r = _find(c, nm)
		if r: return r
	return null

func _scan(n: Node, a: int, g: int) -> void:
	if n is Control and n.is_visible_in_tree():
		var r = n.get_global_rect(); var vp = get_viewport().get_visible_rect()
		if r.position.x < -1 or r.position.y < -1 or r.end.x > vp.end.x+1 or r.end.y > vp.end.y+1:
			off += 1
	for c in n.get_children(): _scan(c,a,g)
