	var lobby = preload("res://scripts/net/NetLobby.gd").new()
	add_child(lobby)
	lobby.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	for i in range(5): await get_tree().process_frame
	lobby._show_select({"players": {1: "房主"}, "picks": {}, "phase": "select"})
	for i in range(5): await get_tree().process_frame
	print("NETART_VP=", get_viewport().get_visible_rect().size)
	var stack = lobby.get("_stack")
	if stack:
		for c in stack.get_children(): print("NETART_BLOCK rect=", c.get_global_rect(), " min=", c.get_combined_minimum_size())
	_scan(lobby)
	var card = _find(lobby, "HeroCard_吕布")
	get_tree().quit()

func _find(n: Node, nm: String) -> Node:
	if n.name == nm: return n
	for c in n.get_children():
		var r = _find(c, nm)
		if r: return r
	return null

func _in_scroll(n: Node) -> bool:
	var p := n.get_parent()
	while p:
		if p is ScrollContainer: return true
		p = p.get_parent()
	return false

func _scan(n: Node) -> void:
	if n is Control and n.is_visible_in_tree() and not _in_scroll(n):
		var r = n.get_global_rect(); var vp = get_viewport().get_visible_rect()
		if r.position.x < -1 or r.position.y < -1 or r.end.x > vp.end.x+1 or r.end.y > vp.end.y+1:
			print("NETART_OFF ", n.get_path(), " rect=", r)
	for c in n.get_children(): _scan(c)
