{"command":"@'
extends Node
func _ready() -> void:
	var bm = preload("res://scripts/core/BattleManager.gd").new()
	add_child(bm)
	for i in range(8): await get_tree().process_frame
	print("VP=", get_viewport().get_visible_rect().size)
	var root = bm.select_ui.get_node_or_null("SelectRoot") if bm.select_ui else null
	if root: _scan(root)
	var bottom = _find(root, "SelectBottom") if root else null
	var top = _find(root, "SelectTop") if root else null
	if top: print("TOP rect=", top.get_global_rect(), " min=", top.get_combined_minimum_size())
	if bottom: print("BOTTOM rect=", bottom.get_global_rect(), " min=", bottom.get_combined_minimum_size())
	get_tree().quit()
func _find(n: Node, nm: String) -> Node:
	if n.name == nm: return n
	for c in n.get_children():
		var r = _find(c, nm)
		if r: return r
	return null
func _in_scroll(n: Node) -> bool:
	var p := n.get_parent()
	while p:
		if p is ScrollContainer: return true
		p = p.get_parent()
	return false
func _scan(n: Node) -> void:
	if n is Control and n.is_visible_in_tree() and not _in_scroll(n):
		var r = n.get_global_rect(); var vp = get_viewport().get_visible_rect()
		if r.position.x < -1 or r.position.y < -1 or r.end.x > vp.end.x+1 or r.end.y > vp.end.y+1:
			print("OFF ", n.get_path(), " rect=", r)
	for c in n.get_children(): _scan(c)
