{"command":"@'
extends Node
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	for i in range(10): await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("鲁班七号")
	for i in range(25): await get_tree().process_frame
	var tur = get_tree().get_first_node_in_group("turrets")
	var minion = get_tree().get_first_node_in_group("minions")
	var jungle = get_tree().get_first_node_in_group("jungle_monsters")
	for pair in [["TURRET", tur], ["MINION", minion], ["JUNGLE", jungle]]:
		var e = pair[1]
		if e == null:
			print(pair[0], " MISSING")
			continue
		var root: Node3D = e.get_hit_flash_root()
		var meshes: Array = []
		UnitVisuals._collect_meshes(root, meshes)
		var before := 0
		for m in meshes:
			if (m as MeshInstance3D).material_overlay != null: before += 1
		e._damage_feedback(50.0, false)
		await get_tree().process_frame
		var mat = root.get_meta("_fx_hit_flash_mat", null)
		var after := 0
		for m in meshes:
			if (m as MeshInstance3D).material_overlay != null: after += 1
		print(pair[0], " root=", root.name, " meshes=", meshes.size(), " overlay=", before, "->", after, " mat=", mat != null, " has_react=", e.has_method("play_hit_react"))
		if pair[0] == "TURRET":
			var p0 = (e._body_vis as Node3D).position
			await get_tree().create_timer(0.05).timeout
			print("TURRET_MOVE=", (e._body_vis as Node3D).position, " base=", e._body_vis_base, " p0=", p0)
	await get_tree().create_timer(0.25).timeout
	for pair in [["TURRET", tur], ["MINION", minion], ["JUNGLE", jungle]]:
		var e = pair[1]
		if e == null: continue
		var mat = e.get_hit_flash_root().get_meta("_fx_hit_flash_mat", null)
		print(pair[0], "_ALPHA_AFTER=", (mat as StandardMaterial3D).albedo_color.a if mat else -1.0)
	get_tree().quit()
