Let's write shaders thoughtfully.

#### cast_range.gdshader
```
shader_type spatial;
render_mode unshaded, blend_add, depth_draw_never, cull_disabled, shadows_disabled;

uniform vec4 tint : source_color = vec4(0.24, 0.68, 1.0, 1.0);
uniform vec4 hot : source_color = vec4(0.80, 0.96, 1.0, 1.0);
uniform float intensity = 1.0;

varying vec2 v_uv;
float band(float r,float center,float width){return 1.0-smoothstep(0.0,width,abs(r-center));}
void vertex(){ v_uv = UV*2.0-1.0; }
void fragment(){
 vec2 p=v_uv; float r=length(p); float a=atan(p.y,p.x); float t=TIME;
 float fill=(1.0-smoothstep(0.0,0.95,r))*0.035;
 float halo=band(r,0.955,0.11)*0.10;
 float rim=band(r,0.962,0.008)*0.95;
 float inner=band(r,0.905,0.0045)*0.30;
 float dashes=smoothstep(0.15,0.95,sin(a*28.0 - t*0.8)*0.5+0.5);
 float ticks=band(r,0.845,0.010)*dashes*0.32;
 float slow=smoothstep(0.45,0.98,sin(a*3.0 - t*0.5 + 1.2)*0.5+0.5);
 float arcs=band(r,0.80,0.006)*slow*0.25;
 float sweep=smoothstep(0.88,1.0,sin(a - t*1.6)*0.5+0.5);
 float pulse=0.88+0.12*sin(t*2.2);
 float alpha=(fill+halo+rim*pulse+inner+ticks+arcs+band(r,0.955,0.025)*sweep*0.28)*intensity;
 alpha*=1.0-smoothstep(0.96,1.0,r);
 alpha=clamp(alpha,0.0,1.0);
 vec3 col=mix(tint.rgb,hot.rgb,clamp(alpha*1.35,0.0,1.0));
 ALBEDO=col*(1.0+alpha*0.8);
 ALPHA=alpha;
}
```
- Angular velocity in angle units; sin(a*3 - t*0.5) arcs rotate slowly. `a` in radians.
- dashes pattern with sin(a*28) creates 28 dashes? Fine.
- Center fill low.
- `rim` at0.962; plane scale range => actual cast range*0.962; good.
- `band(r,0.955,0.11)` halo overlaps rim; additive.
- Alpha can exceed1 before clamp; okay.

#### cast_area.gdshader
