shader_type spatial;
render_mode unshaded, blend_add, depth_draw_never, cull_disabled, shadows_disabled;
uniform ...
uniform float mode = 0.0; //0 area 1 reticle
varying vec2 v_uv;
...
void fragment(){
 vec2 p=v_uv; float r=length(p); float a=atan(p.y,p.x); float t=TIME;
 float pulse=0.9+0.1*sin(t*2.6);
 float alpha=0.0; vec3 col=tint.rgb;
 if (mode <0.5) {
   float fill=(1.0-smoothstep(0.05,0.94,r))*0.075*pulse;
   float halo=band(r,0.90,0.10)*0.08;
   float rim=band(r,0.925,0.011)*0.88;
   float inner=band(r,0.66,0.006)*0.24;
   // crosshair
   float cross=0.0;
   cross+= (1.0-smoothstep(0.0,0.008,abs(p.x)))*(1.0-smoothstep(0.55,0.78,r))*0.20;
   cross+= (1.0-smoothstep(0.0,0.008,abs(p.y)))*(1.0-smoothstep(0.55,0.78,r))*0.20;
   float center=1.0-smoothstep(0.0,0.075,r); alpha... 
   float sweep=smoothstep(0.72,1.0,sin(a - t*1.15)*0.5+0.5);
   float wedge=smoothstep(0.0,0.10,r)*(1.0-smoothstep(0.90,0.96,r))*sweep*0.09;
   alpha=fill+halo+rim*pulse+inner+cross+center*0.20+wedge;
   alpha*=1.0-smoothstep(0.94,1.0,r);
   col=mix(tint.rgb,hot.rgb,clamp(alpha*1.2,0,1));
 } else {
   // target reticle: four brackets + crosshair + outer thin ring + center dot
   float outer=band(r,0.88,0.006)*0.30;
   float br=smoothstep(0.45,0.85,sin(a*4.0+0.8)*0.5+0.5);
   float bracket=band(r,0.72,0.028)*br*0.9;
   float inner=band(r,0.48,0.0045)*0.22;
   float crossx=(1.0-smoothstep(0.0,0.010,abs(p.x)))*(1.0-smoothstep(0.58,0.66,abs(p.y)))*0.28; // vertical line? p.x near0 => line along y
   float crossy=(1.0-smoothstep(0.0,0.010,abs(p.y)))*(1.0-smoothstep(0.58,0.66,abs(p.x)))*0.28;
   float center=1.0-smoothstep(0.0,0.09,r);
   float pulse...
   alpha=(outer+bracket*pulse+inner+crossx+crossy+center*0.5);
   alpha*=1.0-smoothstep(0.94,1.0,r);
   col=mix(tint.rgb,hot.rgb,clamp(alpha*1.5,0,1));
 }
 ALBEDO=col*(1+alpha*.7); ALPHA=clamp(alpha,0,1);
}
```
- Crosshair mask: for x line along y: `abs(p.x)<.01` and `abs(p.y)<.66`; y line along x.
- Target bracket `sin(a*4+0.8)` yields 4 arcs with gaps; good.
- If mode reticle scaled1.2 world radius; bracket radius ~0.8*1.2=0.96; okay.

