shader_type spatial;
render_mode unshaded, blend_add, depth_draw_never, cull_disabled, shadows_disabled;
uniform vec4 tint...
uniform vec4 hot...
uniform float intensity=1;
varying vec2 v_p; // x=-1..1, y=-1..1 along local z

void vertex(){ v_p = vec2(VERTEX.x*2.0, VERTEX.z*2.0); }
void fragment(){
 float x=v_p.x; float y=v_p.y; // y -1 tail, +1 tip
 float t=TIME;
 float ax=abs(x);
