 // flow chevrons
 float flow=sin((y*0.5+0.5)*22.0 - t*7.0 + ax*2.0)*0.5+0.5;
 body_mask += (1.0-smoothstep(0.0,0.55,ax))*smoothstep(0.55,1.0,flow)*0.18;
 // side rails from tail to before head
 float rail_mask=(1.0-smoothstep(0.0,0.04,abs(ax-0.82)))*(1.0-smoothstep(0.25,0.55,y)); 
 // head triangle from y0.42 to1.0; half width shrinks
 float ht=clamp((y-0.40)/0.60,0,1);
 float half=0.92*(1.0-ht);
 float head=step(0.0,y-0.38)*step(ax,half)*0.9;
 float head_edge=smoothstep(0.0,0.05,abs(ax-half))*? wait edge near boundary: 1-smoothstep(0,0.05,abs(ax-half)) gives 1 at edge; use.
 // add outline at outer edge of head
 float edge=1.0-smoothstep(0.03,0.10,abs(ax-half)); edge *= step(0.02,y-0.38)*step(ax, half+0.03)
 // fade near tip
 float tipfade=1.0-smoothstep(0.96,1.0,y);
 float alpha=(body*0.25+center*0.45*body+rails*0.65+head*0.22+edge*0.75)*tipfade;
 // add tail soft glow
 alpha += (1.0-smoothstep(0.0,0.25,abs(y+1.0)))*(1.0-smoothstep(0.0,0.8,ax))*0.2;
 alpha*=intensity;
 ...
}
