			continue
		var spin := 0.55 if i == 0 else (-0.42 if i == 1 else 0.34)
		ring.rotation.y += delta * spin
		ring.position.y = float(_ring_base_y[i]) + sin(_portal_t * 1.2 + i * 1.8) * 0.06
