			if hero.taiyi_q_channeling and hero.taiyi_q_timer > 0.0:
				out.append(_status_entry("引爆", hero.taiyi_q_timer / 5.0, Color(0.80, 0.50, 1.0), 0, "%.1fs" % hero.taiyi_q_timer, true))
	if hero.is_teleporting:
