## 临时：遍历所有英雄技能，验证选人技能详情能按真实公式算出数值（不进场）

func _ready() -> void:
	var bm = load("res://scripts/core/BattleManager.gd").new()
	var empty: Array = []
	var total := 0
	for hero_name in bm.hero_configs.keys():
		bm.selected_hero_type = str(hero_name)
		var ids: Array = bm.hero_configs[hero_name].get("skills", [])
		for idx in ids.size():
			var sk: Skill = SkillDatabase.get_skill(str(ids[idx]))
			if sk == null:
				empty.append("%s/%d null" % [hero_name, idx])
				continue
			total += 1
			var lines: Array = bm._build_skill_tip_lines(sk, idx)
			var joined := "\n".join(lines)
			if not joined.contains("伤害：") and not joined.contains("效果：") and not joined.contains("1级效果："):
				empty.append("%s/%d %s" % [hero_name, idx, sk.skill_name])
	print("TOTAL=", total, " NO_NUMERIC=", empty.size())
	for s in empty:
		print("  EMPTY ", s)
	get_tree().quit()
"}

