{"file_path":"C:\Users\18749\Documents\honor-king\scripts\dev\probe_select_build.gd","content":"extends SceneTree

func _initialize() -> void:
	call_deferred("_run")

func _run() -> void:
	var scene: PackedScene = load("res://scenes/battle.tscn")
	var bm = scene.instantiate()
	root.add_child(bm)
	for i in range(10):
		await process_frame
	print("BM=", bm, " scheme_row=", bm.sel_build_scheme_row)
	bm._on_hero_selected("元流之子")
	bm._on_right_tab_pressed("出装")
	for i in range(4):
		await process_frame
	print("hero=", bm.sel_build_hero, " ids=", bm.sel_build_ids)
	print("builds=", HeroBuildStore.get_builds("元流之子"))
	print("schemes=", bm.sel_build_scheme_row.get_child_count())
	for c in bm.sel_build_scheme_row.get_children():
		print("  ", c.name, " text=", c.text if c is Button else "?", " rect=", c.get_global_rect(), " vis=", c.visible, " disabled=", c.disabled if c is Button else "?")
	var target = null
	for c in bm.sel_build_scheme_row.get_children():
		if c is Button and c.text == "故氏":
			target = c
			break
	print("target=", target)
	if target:
		target.emit_signal("pressed")
		for i in range(2):
			await process_frame
		print("after press ids=", bm.sel_build_ids)
		print("override=", ItemDatabase.get_recommended_override("元流之子"))
		print("active=", bm._current_build_scheme_name())
	quit()
"}

