{"file_path":"C:\Users\18749\Documents\honor-king\scripts\dev\probe_intro.gd","content":"extends Node

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	_run.call_deferred()

func _run() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	get_tree().root.add_child(bm)
	for i in range(180):
		if bm.select_ui != null:
			break
		await get_tree().process_frame
	bm._on_hero_selected("元流之子")
	bm._start_game("元流之子", "flash")
	for i in range(600):
		await get_tree().process_frame
		if bm.hero_selected and bm.intro_active:
			break
	var ai_pos: Vector3 = Vector3.ZERO
	for h in get_tree().get_nodes_in_group("heroes"):
		if h != bm.hero and h.is_ai:
			ai_pos = h.global_position
			break
	print("intro start active=", bm.intro_active, " paused=", get_tree().paused, " ui=", bm.ui.visible, " mm=", bm.minimap.visible, " t=", bm.game_time, " cam=", bm.cam.global_position, " ai=", ai_pos)
	for i in range(30):
		await get_tree().process_frame
	print("mid active=", bm.intro_active, " t=", bm.game_time, " cam=", bm.cam.global_position, " ai=", ai_pos)
	var ai_now: Vector3 = Vector3.ZERO
	for h in get_tree().get_nodes_in_group("heroes"):
		if h != bm.hero and h.is_ai:
			ai_now = h.global_position
			break
	print("ai_still=", ai_now.is_equal_approx(ai_pos))
	for i in range(240):
		await get_tree().process_frame
		if not bm.intro_active:
			break
	print("intro end active=", bm.intro_active, " paused=", get_tree().paused, " ui=", bm.ui.visible, " mm=", bm.minimap.visible, " t=", bm.game_time, " cam=", bm.cam.global_position)
	for i in range(30):
		await get_tree().process_frame
	print("after t=", bm.game_time, " minion_timer=", bm.minion_spawn_timer, " minions=", get_tree().get_nodes_in_group("minions").size())
	get_tree().quit()
"}

