	print("progress_seq=", ",".join(seen))
	print("loading_gone building=", bm.building_battle, " intro=", bm.intro_active, " waiting=", bm._intro_waiting, " paused=", get_tree().paused, " ui=", bm.ui.visible)
	for i in range(240):
		await get_tree().process_frame
		if not bm.intro_active:
			break
	print("intro_end intro=", bm.intro_active, " paused=", get_tree().paused, " ui=", bm.ui.visible, " t=", bm.game_time, " minions=", get_tree().get_nodes_in_group("minions").size())
	get_tree().quit()
"}

