func _add_lane_plane_net(center: Vector3, size: Vector2, diag: bool) -> void:
	var plane := MeshInstance3D.new()
	var pm := PlaneMesh.new()
	pm.size = size
	plane.mesh = pm
	if diag:
		plane.rotation_degrees = Vector3(0.0, -45.0, 0.0)
