			cm.size = Vector3(0.6, 0.22, size.y + 1.0)
			curb.position = Vector3((size.x * 0.5 + 0.25) * s, -0.04, 0.0)
		curb.mesh = cm
		curb.material_override = curb_mat
		plane.add_child(curb)
	$World.add_child(plane)"}

